{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The search was restricted to randomized controlled trials (RCTs) written in English and published in peer-reviewed journals. The PICOS (Participants, Interventions, Comparisons, Outcomes, Study Designs) checklist was used to identify the inclusion criteria in this review. 17 Participants (P): This review included trials if they targeted persons with stroke (ischemic and hemorrhagic), regardless of comorbidities and any previous treatments, but excluded those with manic or psychotic episodes/symptoms in order to reduce biases associated with non-target symptoms. Participants were included whether or not they received pharmacological interventions (any dosage or duration) for depression or other illnesses. Interventions (I) and controls (C): This review considered trials that compared the effects of NPIs for post-stroke individuals with depressive symptoms (eg, music therapy, massage therapy, behavioral therapy, or physical exercise with any frequency, intensity, or duration) to control conditions, such as usual treatment. Outcomes (O): The primary outcome of this review was depressive symptoms, measured by any validated depression scale. Study designs (S): This review considered any RCT with a pre-post design, meaning that outcomes were measured at pre-intervention, post-intervention, and follow-up.",
      "reason": "The eligibility criteria specify study characteristics using PICOS, including participants (stroke with exclusions), study design (RCT pre-post with follow-up), outcomes (depressive symptoms measured by validated depression scale), and the intervention/comparison structure for inclusion."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The search was restricted to randomized controlled trials (RCTs) written in English and published in peer-reviewed journals.",
      "reason": "The review specifies report characteristics including language (English) and publication status (peer-reviewed journals)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_5",
      "quote": "Trials published between January 2000 and August 2018 were considered for inclusion; this date range reflects findings from an initial search in MEDLINE and CINAHL, which showed no relevant trials before 2000.",
      "reason": "It provides a publication date range, but the evidence does not explicitly state inclusion criteria for dissemination year beyond this range, nor whether unpublished/other report statuses were considered."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence is provided distinguishing exclusions because outcomes were not measured versus exclusions because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PARTIAL",
      "chunk_id": "text_12",
      "quote": "These trials were grouped into four types: CAT (n = 5), exercise (n = 4), psychosocial therapy (n = 2), and multifactorial therapy (n = 2) (Table 2).",
      "reason": "Groups used for synthesis are specified (CAT, exercise, psychosocial therapy, multifactorial therapy), but the evidence does not clearly show that each group is explicitly linked to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "This review included trials if they targeted persons with stroke (ischemic and hemorrhagic), regardless of comorbidities and any previous treatments, but excluded those with manic or psychotic episodes/symptoms in order to reduce biases associated with non-target symptoms.",
      "reason": "A rationale is provided for an eligibility restriction (excluding manic/psychotic episodes to reduce bias)."
    }
  ],
  "confidence": 72
}

